from collections import deque
import sys


def lag_features(sales):
    """sales[0] is day 1. For each day d return (d, sales 7 days earlier, mean of the 7 days BEFORE d), using None while fewer than 7 earlier days exist. Never use day d's own sales."""
    window, total, out = deque(), 0, []
    for day, value in enumerate(sales, 1):
        if len(window) == 7:
            out.append((day, window[0], total / 7))    # the window holds days day-7 .. day-1 only
        else:
            out.append((day, None, None))
        window.append(value)                          # today joins AFTER its features were built
        total += value
        if len(window) > 7:
            total -= window.popleft()
    return out


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    sales = list(map(int, data[1:1 + n]))
    for day, lag7, roll7 in lag_features(sales):
        print(day, "NA" if lag7 is None else lag7, "NA" if roll7 is None else format(roll7, ".1f"))


main()

import sys


def top_ngrams(text, n, k):
    """Lower-case the text, join its words with '_' and put one '_' at each end. Return the k most frequent character n-grams as (gram, count), most frequent first, ties in string order."""
    padded = "_" + "_".join(text.lower().split()) + "_"
    counts = {}
    for i in range(len(padded) - n + 1):
        gram = padded[i:i + n]
        counts[gram] = counts.get(gram, 0) + 1
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:k]


def main():
    data = sys.stdin.read().split("\n")
    n, k = map(int, data[0].split())
    for gram, count in top_ngrams(data[1], n, k):
        print(gram, count)


main()
